function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function hashStr(s){ var h=2166136261>>>0; for(var i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619)>>>0; } return h>>>0; }
function cn(n){ var a=['零','一','二','三','四','五','六','七','八','九','十']; return n<=10?a[n]:String(n); }
var TYPES={
  '填空题':function(t,i){return '请根据《'+t+'》的内容，填写第 '+i+' 个空：____________________';},
  '简答题':function(t,i){return '简述《'+t+'》中第 '+i+' 个核心要点。';},
  '判断题':function(t,i){return '判断（ ）：《'+t+'》仅适用于单一固定场景，不存在例外。';},
  '选择题':function(t,i){return '关于《'+t+'》，下列说法错误的是第 '+i+' 项？';},
  '连线题':function(t,i){return '将左侧与《'+t+'》相关的术语与右侧解释连线（第 '+i+' 组）。';},
  '计算题':function(t,i){return '计算并写出第 '+i+' 道与《'+t+'》相关的题目步骤。';}
};
function buildWorksheet(o){
  o=o||{};
  var subject=String(o.subject||'通用').trim()||'通用';
  var grade=String(o.grade||'初中').trim()||'初中';
  var topic=String(o.topic||'').trim()||'（待填写主题）';
  var types=splitLines(o.types);
  if(!types.length) types=['填空题','简答题','判断题'];
  var per=parseInt(o.per,10)||4; if(per<1)per=1; if(per>10)per=10;
  var lines=[], total=0, answers=[];
  lines.push('# 练习题：'+subject+'《'+topic+'》');
  lines.push('');
  lines.push('- 学段：'+grade+'　题目数：'+(types.length*per));
  lines.push('');
  types.forEach(function(tp,si){
    lines.push('## '+cn(si+1)+'、'+tp);
    for(var i=1;i<=per;i++){
      total++;
      lines.push(total+'. '+((TYPES[tp]||function(t,k){return '请完成与《'+t+'》相关的第 '+k+' 题。';})(topic,i)));
      var ans='（参考教材 / 教师评定）';
      if(tp==='判断题'){ ans=(hashStr(topic+i)%2===0)?'正确':'错误'; }
      else if(tp==='选择题'){ ans='正确答案：'+String.fromCharCode(65+(hashStr(topic+i)%4)); }
      answers.push({n:total, type:tp, ans:ans});
    }
    lines.push('');
  });
  lines.push('## 参考答案');
  answers.forEach(function(a){ lines.push('- 第 '+a.n+' 题（'+a.type+'）：'+a.ans); });
  return {title:topic+' 练习题', sectionCount:types.length, itemCount:total,
          total:total, answers:answers.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, hashStr:hashStr, cn:cn, buildWorksheet:buildWorksheet};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WorksheetForgePure = EXPORTS; }
